module benchmark/solution

func fizzBuzz(n: int) -> () ! {IO} {
  if n > 100 then ()
  else {
    println(if n % 15 == 0 then "FizzBuzz"
      else if n % 3 == 0 then "Fizz"
      else if n % 5 == 0 then "Buzz"
      else show(n));
    fizzBuzz(n + 1)
  }
}

export func main() -> () ! {IO} = fizzBuzz(1)
